package com.prokxi.dimples.domain;

import java.util.Objects;
import java.util.UUID;

/**
 * Identifies a course. Generated by the application when the course is created
 * (decision-2).
 */
public record CourseId(UUID value) {

	public CourseId {
		Objects.requireNonNull(value, "value must not be null");
	}

	public static CourseId generate() {
		return new CourseId(UUID.randomUUID());
	}

}
